export interface SwitchTrackProps extends Omit<React.SVGProps<SVGSVGElement>, 'children'> {
  fillImageHref?: string
  leftActiveClassName?: string
  leftInactiveClassName?: string
  rightActiveClassName?: string
  rightInactiveClassName?: string
}

export interface SwitchTrackPatternDefsProps {
  fillImageHref?: string
  fillPatternId: string
  inactiveFilterId: string
  patternDurationSeconds?: number
  patternRepeatX?: number
  patternRepeatY?: number
  patternTileSize?: number
}

function usePrefersReducedMotion() {
  return React.useSyncExternalStore(
    React.useCallback((onStoreChange) => {
      const media = window.matchMedia(REDUCED_MOTION_QUERY)

      media.addEventListener('change', onStoreChange)

      return () => media.removeEventListener('change', onStoreChange)
    }, []),
    () => window.matchMedia(REDUCED_MOTION_QUERY).matches,
    () => false
  )
}

function SwitchTrackPatternDefs({
  fillImageHref = '/_images/backgrounds/camo-green.png',
  fillPatternId,
  inactiveFilterId,
  patternDurationSeconds = SWITCH_TRACK_PATTERN_DURATION_SECONDS,
  patternRepeatX = SWITCH_TRACK_PATTERN_REPEAT_X,
  patternRepeatY = SWITCH_TRACK_PATTERN_REPEAT_Y,
  patternTileSize = SWITCH_TRACK_PATTERN_TILE_SIZE,
}: SwitchTrackPatternDefsProps) {
  const prefersReducedMotion = usePrefersReducedMotion()
  const patternAnimationX = -patternTileSize * patternRepeatX
  const patternAnimationY = -patternTileSize * patternRepeatY

  return (
    <>
      <filter id={inactiveFilterId} colorInterpolationFilters="sRGB">
        <feColorMatrix type="matrix" values={SWITCH_TRACK_INACTIVE_FILTER_VALUES} />
      </filter>
      <pattern
        id={fillPatternId}
        patternUnits="userSpaceOnUse"
        width={patternTileSize}
        height={patternTileSize}
      >
        {!prefersReducedMotion ? (
          <animateTransform
            attributeName="patternTransform"
            type="translate"
            from="0 0"
            to={`${patternAnimationX} ${patternAnimationY}`}
            dur={`${patternDurationSeconds}s`}
            repeatCount="indefinite"
          />
        ) : null}
        <image
          href={fillImageHref}
          width={patternTileSize}
          height={patternTileSize}
          preserveAspectRatio="xMidYMid meet"
        />
      </pattern>
    </>
  )
}

function SwitchTrack({
  fillImageHref = '/_images/backgrounds/camo-green.png',
  leftActiveClassName,
  leftInactiveClassName,
  rightActiveClassName,
  rightInactiveClassName,
  ...props
}: SwitchTrackProps) {
  const id = React.useId().replace(/:/g, '')
  const leftClipId = `switch-track-left-${id}`
  const rightClipId = `switch-track-right-${id}`
  const fillPatternId = `switch-track-fill-${id}`
  const inactiveFilterId = `switch-track-inactive-${id}`

  return (
    <svg
      width={SWITCH_TRACK_WIDTH}
      height={SWITCH_TRACK_HEIGHT}
      viewBox={SWITCH_TRACK_VIEW_BOX}
      fill="none"
      focusable="false"
      aria-hidden="true"
      {...props}
    >
      <defs>
        <clipPath id={leftClipId}>
          <path d={SWITCH_TRACK_LEFT_PATH} />
        </clipPath>
        <clipPath id={rightClipId}>
          <path d={SWITCH_TRACK_RIGHT_PATH} />
        </clipPath>
        <SwitchTrackPatternDefs
          fillImageHref={fillImageHref}
          fillPatternId={fillPatternId}
          inactiveFilterId={inactiveFilterId}
        />
      </defs>
      <g clipPath={`url(#${leftClipId})`}>
        <rect
          className={leftActiveClassName}
          x="167"
          y="30"
          width="16498"
          height="2119"
          fill={`url(#${fillPatternId})`}
        />
        <rect
          className={leftInactiveClassName}
          x="167"
          y="30"
          width="16498"
          height="2119"
          fill={`url(#${fillPatternId})`}
          filter={`url(#${inactiveFilterId})`}
        />
      </g>
      <g clipPath={`url(#${rightClipId})`}>
        <rect
          className={rightActiveClassName}
          x="167"
          y="30"
          width="16498"
          height="2119"
          fill={`url(#${fillPatternId})`}
        />
        <rect
          className={rightInactiveClassName}
          x="167"
          y="30"
          width="16498"
          height="2119"
          fill={`url(#${fillPatternId})`}
          filter={`url(#${inactiveFilterId})`}
        />
      </g>
    </svg>
  )
}

export {
  SWITCH_TRACK_INACTIVE_FILTER_VALUES,
  SWITCH_TRACK_PATTERN_DURATION_SECONDS,
  SWITCH_TRACK_PATTERN_REPEAT_X,
  SWITCH_TRACK_PATTERN_REPEAT_Y,
  SWITCH_TRACK_PATTERN_TILE_SIZE,
  SwitchTrack,
  SwitchTrackPatternDefs,
}
